export async function fillVisitForm(page, date, description, durationMinutes) {
    await page.locator("#date").fill(date);
    await page.locator("#description").fill(description);
    await page.locator("#durationMinutes").fill(durationMinutes);
}

export async function setVisitDuration(page, durationMinutes) {
    await page.getByRole("spinbutton", { name: "Duration (minutes)" }).fill(durationMinutes);
}

export async function setVisitDurationById(page, durationMinutes) {
    await page.locator("#durationMinutes").fill(durationMinutes);
}

export async function submitVisitEditForm(page) {
    await page.getByRole("button", { name: "Update Visit" }).click();
}
